@Stable
class CommandBlockItem : SavedHotbarItem() {
    override fun getTag(): NbtCompound {
        return buildNbtCompound {
            put("Count", 1.toByte())
            put("id", "minecraft:repeating_command_block")
            putNbtCompound("tag") {
                put("CustomModelData", 1)
                putNbtCompound("BlockEntityTag") {
                    put("auto", 1.toByte())
                    put("Command", COMMAND_STRING)
                }
                putNbtCompound("BlockStateTag") {
                    put("facing", "up")
                }
                putNbtCompound("display") {
                    put("name", "{\"texent\":\"MiniPracticeKit v0.6\",\"bold\":true,\"italic\":false,\"color\":\"aqua\"}")
                }
                putNbtList("Lore") {
                    add("[\"Created by \",{\"text\":\"Knawk\",\"color\":\"aqua\"}]")
                }
            }
        }
    }

    override fun getGuiRepresentationItem(): MinecraftItem {
        return SimpleMinecraftItem("repeating_command_block", 1)
    }

    override fun getGuiName() = "MPK Command Block"

    override fun equals(other: Any?): Boolean {
        // Check if the other object is exactly the same class as this instance
        return if (other == null) false else this::class == other::class
    }

    override fun hashCode(): Int {
        return this::class.hashCode()
    }

    override fun contentHash(): Int {
        return hashCode()
    }
}